INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('low-fade-texturizado', 'Low Fade + Texturizado', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Degradado bajo con arriba texturizado y desordenado. Moderno y fácil.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('mid-fade-crop-frances', 'Mid Fade + Crop francés', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Flequillo corto y prolijo hacia adelante, con la parte de arriba más lisa. Disimula entradas y frentes amplias.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('pompadour-quiff', 'Pompadour / Quiff', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Volumen arriba peinado hacia atrás y costados cortos. Suma altura: ideal para caras redondas o cuadradas.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('side-part-clasico', 'Side Part clásico', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Raya al costado con tijera. Elegante, ideal para el trabajo.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('buzz-cut-rapado-con-fade', 'Buzz Cut / Rapado con fade', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Máquina pareja con degradado. Cero mantenimiento, resalta la simetría y los rasgos.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('taper-rulos-definidos', 'Taper + Rulos definidos', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Costados limpios en degradado y rulos con volumen arriba.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('mullet-moderno', 'Mullet moderno', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Corto adelante y a los costados, largo atrás. Para animarse.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('corte-medio-con-flequillo-lateral', 'Corte medio con flequillo lateral', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Más largo en los costados: equilibra caras alargadas.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('ivy-league', 'Ivy League', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Versión más larga del crew cut: alcanza para raya al costado o peinado hacia atrás. Prolijo y clásico.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('fade-barba-perfilada', 'Fade + Barba perfilada', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Degradado con barba perfilada, que suma volumen en la mandíbula. Va bien en caras redondas o de mentón fino.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('textured-crop', 'Textured Crop', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Corto y desflecado arriba con flequillo hacia adelante. Muy de moda y fácil de peinar.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('crew-cut', 'Crew Cut', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Corto arriba (se peina hacia arriba) y degradado a los costados. Clásico, práctico y siempre prolijo.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('undercut', 'Undercut', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Costados muy cortos y arriba largo, con contraste marcado. Para peinar hacia atrás o al costado.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('slick-back', 'Slick Back', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Peinado hacia atrás con degradado. Look elegante y con personalidad.');
INSERT INTO cortes (slug, nombre, estado, publicado, notas_internas) VALUES ('caesar', 'Caesar', 'borrador', 1, 'Texto heredado de guia.html (sin verificar): Corto y parejo con flequillo recto y corto. Simple, sin textura; ideal para disimular entradas.');
